  "ae.cool": "Cooling is {g}% above its normalised design this month. {a} runs {c}% below its efficiency curve, drifting for {d} days; likely cause, to check on site: condenser coil fouling. The coil clean is work order {w} ({s}).",
  "ae.peakOver": "The forecast peak is {p} kW of hourly demand against the {c} kW contract, on {d}: it exceeds the contract in {m} while the chiller fault persists. With {a} fixed (work order {w}), the engine forecasts {f} kW.",
  "ae.peakOk": "The forecast peak is {p} kW of hourly demand, within the {c} kW contract ({d}).",
  "ae.cost": "{m} is forecast at {v} kWh ({lo} to {hi}); the budget is {b} kWh. The cost is shown in the executive lens.",
  "ae.costExec": "{m} is forecast at {v} kWh ({lo} to {hi}), about {aed} AED at {r} AED per kWh; the budget is {b} kWh.",
  "ae.monthEnd": "This month is projected at {v} kWh ({lo} to {hi}) against a budget of {b} kWh; {m} kWh so far.",
  "ae.mtd": "{m} kWh so far this month, {t} kWh of it today; this month's budget is {b} kWh.",
  "ae.filter": "The AHU-1 filter reaches its {l} Pa limit in about {d} days ({lo} to {hi}); it reads {p} Pa now. The change is planned: {w}.",
  "ae.proveOk": "Yes. The AHU-2 cooling valve repair (WO-5077) worked: supply air ran {b} K above set point before the fix and {a} K after, uncertainty {u} K. Verdict: Recovered.",
  "ae.proveNo": "Not proven yet: supply air ran {b} K above set point before the fix and {a} K after, uncertainty {u} K.",
  "ae.doors": "{n} doors are not secure: {f} forced, {h} held open, {o} open and {u} unlocked outside their schedule. Forced: {fl}. Held open: {hl}.",
  "ae.evac": "With the scenario's fire, Level {l} is clear in {c} min and everyone is out of the building in {o} min; all transfers complete in {t} min. {n} people, {s} stranded, as at {h}.",
  "ae.cams": "{n} of {of} cameras are offline: {l}. The longest, {x}, for {h} hours. {r} more are online but not recording.",
  "ae.beds": "Beds occupied: {o} of {n}, {i} of them in contact isolation; patients needing help to leave: {a}. Beds free: {f}.",
  "ae.nurse": "Open nurse calls: {n}; the oldest, at bed {b}, for {o} min. The median answer over the last {w} hours is {m} min ({d} calls).",
  "ae.nurseNone": "No nurse call is open. The median answer over the last {w} hours is {m} min ({d} calls).",
  "ae.gen": "{g} is ready on standby with {f}% fuel; its last monthly run was {d} days ago. {u} carries {ul}% load with {ur} min on battery.",
  "ae.genLate": "{g} is on standby with {f}% fuel, but its monthly run is {l} days overdue (the last run was {d} days ago; PM-0311). {u} carries {ul}% load with {ur} min on battery.",
  "ae.wos": "Open work orders: {n}; past their due time: {l} ({list}).",
  "ae.pm": "Planned maintenance done on time over the last {w} days: {list}. Work orders closed within their target: {s}%.",
  "ae.rh": "Sensed rooms outside the {lo} to {hi}% humidity band: {n} of {of}. {list}.",
  "ae.o2": "The oxygen line reads {p} bar against its {l} bar low alarm (normal {n} bar), for {h} hours; likely cause, to check on site: the manifold changeover regulator. Work order {w} is assigned.",
  "ae.occ": "{n} people are in the building now, against a capacity of {c}; today's peak so far is {p}, the average peak over {w} days {a}.",
  "ae.data": "{s} points are stale and {o} devices offline, of {n} points; {p}% online. Degraded: {list}.",
  "ae.ce": "In the fire scenario, {o} of {n} expected responses were observed and {a} devices went to alarm; acknowledged after {k} s. {u} did not stop. Likely cause, to check on site: {c}. Work order {w} is in the CMMS after the event.",
