  "e14.site": "How this works on site",
  "e14.siteHide": "Hide how this works on site",
  "e14.siteT": "How this works on site, on premises",
  "e14.site.land.1.k": "Alarms:",
  "e14.site.land.1.v": "read from EKO Framework (BACnet) on the site network. EKO reads only; nothing is written to the plant. In this demo they come from EKO's building data engine.",
  "e14.site.land.2.k": "Work orders:",
  "e14.site.land.2.v": "read from the site CMMS through EKO's server connector. In this demo they are the engine's demo work orders.",
  "e14.site.land.3.k": "Handover:",
  "e14.site.land.3.v": "EKO's own record, kept on the EKO server on site and locked when it is sent. Without the server it stays in this browser, and the Brief says so.",
  "e14.site.land.4.k": "The sentence:",
  "e14.site.land.4.v": "built by code from the facts; the on-site model only rewords it, and the number guard rejects any figure the data did not give.",
  "e14.site.land.5.k": "Acknowledge:",
  "e14.site.land.5.v": "recorded in EKO with your name and the time. Whether it is also sent to EKO is the site's decision, still open.",
  "e14.site.land.6.k": "The AI glow:",
  "e14.site.land.6.v": "shown only on text the on-site model wrote; text built by the template is marked template.",
  "e14.site.pred.1.k": "The point:",
  "e14.site.pred.1.v": "the reading's history from EKO (the BACnet point's trend). In this demo, the building data engine's history.",
  "e14.site.pred.2.k": "The forecast:",
  "e14.site.pred.2.v": "a straight line fitted by code on the EKO server over the last 30 days, with its range. Not the AI. No reliable fit, no forecast.",
  "e14.site.pred.3.k": "The work order:",
  "e14.site.pred.3.v": "read from the site CMMS. EKO opens it; creating one needs the client to enable EKO's CMMS connector.",
  "e14.site.pred.4.k": "The proof:",
  "e14.site.pred.4.v": "the EKO history before and after the CMMS closing time of the work order.",
  "e14.site.prove.1.k": "The data:",
  "e14.site.prove.1.v": "EKO reads the CMMS closing time of the work order and the EKO history of the reading, and compares the days before with the days after, by code on the EKO server.",
  "e14.site.prove.2.k": "The verdict:",
  "e14.site.prove.2.v": "Recovered only when the improvement is larger than its uncertainty and the reading holds inside its band. Otherwise it says Partly recovered, Not recovered or Too early to tell.",
  "e14.site.prove.3.k": "The weather:",
  "e14.site.prove.3.v": "the after window is scaled by the cooling degree days of the two windows, so a cooler month cannot look like a fix. The demo marks this as a stand-in.",
  "e14.site.exec.1.k": "Energy:",
  "e14.site.exec.1.v": "the site's meters through EKO, summed by code on the EKO server. In this demo, the building data engine.",
  "e14.site.exec.2.k": "The budget:",
  "e14.site.exec.2.v": "the same month last year less the saving target, a demo assumption the client confirms.",
  "e14.site.exec.3.k": "The cost:",
  "e14.site.exec.3.v": "one tariff record for every figure, provisional until the client confirms it. Shown to the executive and the facility manager only.",
  "e14.site.exec.4.k": "The risks:",
  "e14.site.exec.4.v": "the alarms from EKO, the work orders from the CMMS and the forecast, ranked by code; the AI only explains.",
  "e14.site.exec.5.k": "The report:",
  "e14.site.exec.5.v": "generated on the EKO server from the same figures, with the standard footer. Nothing leaves the site.",
  "e14.site.asset.1.k": "Nameplate:",
  "e14.site.asset.1.v": "read from the model (IFC) at commissioning, locally; the model is never changed. Fields the model does not hold are demo values, marked Demo.",
  "e14.site.asset.2.k": "Points:",
  "e14.site.asset.2.v": "the EKO points over BACnet, with their trends from the EKO history. In this demo, the building data engine.",
  "e14.site.asset.3.k": "O&M:",
  "e14.site.asset.3.v": "the next task and the service history from the site CMMS; documents from the client's document store, titles only in the demo.",
  "e14.site.asset.4.k": "Predict:",
  "e14.site.asset.4.v": "a straight line fitted by code over 30 days, with its range; no reliable fit, no forecast.",
  "e14.site.asset.5.k": "Read only:",
  "e14.site.asset.5.v": "EKO writes nothing to the plant; opening a work order opens the CMMS record.",
